// foldFixture is testdata/health_fold.json: rows before and after the
// pipeline's prune_once (engine/prune.py) ran on them.
type foldFixture struct {
	Now           string   `json:"now"`
	Folded        int64    `json:"folded"`
	RollupsPruned int64    `json:"rollups_pruned"`
	Input         [][4]any `json:"input"`
	Output        [][4]any `json:"output"`

	parsedNow time.Time
	in, out   []hsRow
}

func loadFold(t *testing.T) *foldFixture {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "health_fold.json"))
	if err != nil {
		t.Fatal(err)
	}
	var f foldFixture
	must(t, json.Unmarshal(b, &f))
	conv := func(rs [][4]any) []hsRow {
		out := make([]hsRow, 0, len(rs))
		for _, r := range rs {
			at, ok := parseTime(r[0].(string))
			if !ok {
				t.Fatalf("fixture time %v", r[0])
			}
			out = append(out, hsRow{at: at, host: r[1].(string), metric: r[2].(string), value: r[3].(float64)})
		}
		return out
	}
	f.in, f.out = conv(f.Input), conv(f.Output)
	f.parsedNow, _ = parseTime(f.Now)
	return &f
}

func sortRows(rs []hsRow) {
	sort.Slice(rs, func(i, j int) bool {
		a, b := rs[i], rs[j]
		if a.metric != b.metric {
			return a.metric < b.metric
		}
		if a.host != b.host {
			return a.host < b.host
		}
		return a.at.Before(b.at)
	})
}

// The hub's health fold gives what the pipeline's gave: the same rollup
// buckets, means and 30-day prune, on the rows the Python fold was run on
// (testdata/health_fold.json, generated by gen_health_fold.py). Folding
// again, or twice at once, changes nothing.
func TestHealthFoldMatchesThePipeline(t *testing.T) {
	f := loadFold(t)
	eachDB(t, func(t *testing.T, db *sql.DB, driver string) {
		clk := &fakeClock{t: f.parsedNow}
		c := newTestCache(db, driver, clk, 0)
		rows := make([]healthRow, len(f.in))
		for i, r := range f.in {
			rows[i] = healthRow(r)
		}
		if _, err := c.upsertHealth(bg, db, rows); err != nil {
			t.Fatal(err)
		}
		c.prune(bg)
		st := c.Snapshot().Rollups
		if st.Folded != f.Folded || st.Pruned != f.RollupsPruned {
			t.Fatalf("folded %d (pipeline %d), pruned %d (pipeline %d)", st.Folded, f.Folded, st.Pruned, f.RollupsPruned)
		}
		check := func(when string) {
			t.Helper()
			got := healthRows(t, db, "")
			want := append([]hsRow(nil), f.out...)
			sortRows(got)
			sortRows(want)
			if len(got) != len(want) {
				t.Fatalf("%s: %d rows, pipeline %d", when, len(got), len(want))
			}
			for i := range got {
				g, w := got[i], want[i]
				if g.host != w.host || g.metric != w.metric || !g.at.Equal(w.at) ||
					math.Abs(g.value-w.value) > 1e-9*math.Max(1, math.Abs(w.value)) {
					t.Fatalf("%s: row %d = %s, pipeline %s", when, i, g, w)
				}
			}
		}
		check("first fold")
		c.prune(bg)
		check("second fold")
		if st := c.Snapshot().Rollups; st.Folded != 0 || st.Buckets != 0 {
			t.Fatalf("a second fold folded %+v", st)
		}

		if driver != "postgres" {
			return // one SQLite connection: folds cannot overlap
		}
		// two folds at once (two hubs, or a restart mid-fold) over fresh raw
		// rows: each row folded once
		must2(t, db, `DELETE FROM health_samples`)
		if _, err := c.upsertHealth(bg, db, rows); err != nil {
			t.Fatal(err)
		}
		other := newTestCache(db, driver, clk, 0)
		var wg sync.WaitGroup
		var n1, n2 int64
		var e1, e2 error
		wg.Add(2)
		go func() { defer wg.Done(); _, n1, e1 = c.foldHealth(bg, clk.Now()) }()
		go func() { defer wg.Done(); _, n2, e2 = other.foldHealth(bg, clk.Now()) }()
		wg.Wait()
		if e1 != nil || e2 != nil {
			t.Fatalf("concurrent folds: %v / %v", e1, e2)
		}
		c.prune(bg) // a fold that met the other's rows stops early; the next one finishes
		if st := c.Snapshot().Rollups; n1+n2+st.Folded != f.Folded {
			t.Fatalf("concurrent folds took %d + %d (+ %d) rows, want %d", n1, n2, st.Folded, f.Folded)
		}
		check("concurrent folds")
	})
}

// Cache rows past the window and read positions of day folders before it
// are pruned; the window's rows stay; the oldest and newest rows are
// reported.
func TestPruneTheWindow(t *testing.T) {
	eachDB(t, func(t *testing.T, db *sql.DB, driver string) {
		clk := newClock("2026-10-19T12:00:00Z")
		c := newTestCache(db, driver, clk, 6*time.Hour)
		p := agent.Proc{WorkerID: "w", IP: "10.0.0.1", Host: "h"}
		for _, at := range []time.Time{
			time.Date(2026, 10, 19, 5, 0, 0, 0, time.UTC), // past the window
			time.Date(2026, 10, 19, 7, 0, 0, 0, time.UTC),
			time.Date(2026, 10, 19, 11, 0, 0, 0, time.UTC),
		} {
			c.Metrics(p, frame(at, 1), nil, false)
			c.Logs(p, []agent.LogRecord{{TS: at.Format(time.RFC3339), Level: "info", Event: "e"}})
		}
		c.flushLogs(bg)
		c.flushMetrics(bg)
		for _, day := range []string{"2026-10-17", "2026-10-18", "2026-10-19"} {
			if _, err := c.exec(bg, db, `INSERT INTO cluster_cache_files (kind, ip, day, worker, root, read_to)
VALUES ('logs', '10.0.0.1', $1, 'w', '/x', 10)`, day); err != nil {
				t.Fatal(err)
			}
		}
		c.prune(bg)
		if n := count(t, db, `SELECT count(*) FROM cluster_log_cache`); n != 2 {
			t.Fatalf("logs = %d", n)
		}
		if n := count(t, db, `SELECT count(*) FROM cluster_metrics_cache`); n != 2 {
			t.Fatalf("frames = %d", n)
		}
		// the window starts 2026-10-19 06:00: the day before it is kept, older go
		if n := count(t, db, `SELECT count(*) FROM cluster_cache_files`); n != 2 {
			t.Fatalf("read positions = %d", n)
		}
		st := c.Snapshot()
		if st.Logs.Oldest == nil || !st.Logs.Oldest.Equal(time.Date(2026, 10, 19, 7, 0, 0, 0, time.UTC)) ||
			!st.Logs.Newest.Equal(time.Date(2026, 10, 19, 11, 0, 0, 0, time.UTC)) || st.Rollups.At == nil {
			t.Fatalf("stats = %+v", st)
		}
	})
}
